"""FastAPI binding over `Store` and `UserStore`: the viewer's HTTP surface."""

from __future__ import annotations

from typing import Any, Callable

from fastapi import Body, FastAPI, Query
from fastapi.responses import JSONResponse

from cyclops import config
from cyclops.ui.store import DEFAULT_MAX_POINTS, Store
from cyclops.ui.user_store import UserStore, UserStoreError


def _json(payload: Any, status: int = 200) -> JSONResponse:
    return JSONResponse(content=payload, status_code=status)


def _answer(call: Callable[[], Any]) -> JSONResponse:
    """Run one store read: a refusal ({exists: false, error}) is a 422, a bad value too."""
    try:
        payload = call()
    except (ValueError, TypeError, OverflowError) as exc:
        return _json({"exists": False, "error": str(exc), "hint": "check the query parameters"}, 422)
    if isinstance(payload, dict) and payload.get("exists") is False and "error" in payload:
        return _json(payload, 422)
    return _json(payload)


def create_app(store: Store | None = None, users: UserStore | None = None) -> FastAPI:
    """Build the FastAPI app bound to one `Store` (one artifact root) and its `UserStore`."""
    if store is None:
        store = Store()
    if users is None:
        users = UserStore(store.root)
    app = FastAPI(title="cyclops")

    @app.exception_handler(UserStoreError)
    async def _user_error(_request, exc: UserStoreError) -> JSONResponse:
        return _json({"exists": False, "error": exc.error, "hint": exc.hint}, exc.status)

    def _get(path: str, fn: Callable[..., Any]) -> None:
        app.add_api_route(path, fn, methods=["GET"])

    @app.get("/api/roots")
    def roots():
        return _answer(store.roots)

    @app.get("/api/quotes")
    def quotes():
        return _answer(store.quotes)

    @app.get("/api/meta")
    def meta():
        return _answer(store.meta)

    @app.get("/api/bars/{rung}")
    def bars(rung: str, start: str | None = None, end: str | None = None,
             max_points: int = Query(DEFAULT_MAX_POINTS, ge=1, le=20000),
             root: str = config.ASSET):
        return _answer(lambda: store.bars(rung, start, end, max_points, root))

    @app.get("/api/bars/{rung}/windows")
    def windows(rung: str, stamps: str | None = None,
                before: int = Query(40, ge=0), after: int = Query(20, ge=0)):
        parts = [s.strip() for s in (stamps or "").split(",") if s.strip()]
        return _answer(lambda: store.bar_windows(rung, parts, before, after))

    @app.get("/api/features/{rung}")
    def features(rung: str, cols: str | None = None, start: str | None = None,
                 end: str | None = None,
                 max_points: int = Query(DEFAULT_MAX_POINTS, ge=1, le=20000),
                 root: str = config.ASSET):
        names = [c.strip() for c in cols.split(",") if c.strip()] if cols else None
        return _answer(lambda: store.features(rung, names, start, end, max_points, root))

    @app.get("/api/regimes")
    def regimes(start: str | None = None, end: str | None = None, rung: str = "1h",
                root: str = config.ASSET):
        return _answer(lambda: store.regimes(start, end, rung, root))

    @app.get("/api/bar/{ts}")
    def bar(ts: str, rung: str = "1h"):
        return _answer(lambda: store.bar_detail(ts, rung))

    @app.get("/api/patterns/{rung}/similar")
    def similar(rung: str, ts: str | None = None, pattern: str | None = None,
                k: int = Query(config.PATTERN_SIM_K, ge=1), layer: str = "cell",
                metric: str = "euclid"):
        return _answer(lambda: store.patterns_similar(rung, ts, k, layer, metric, pattern))

    @app.get("/api/patterns/{rung}")
    def patterns(rung: str, start: str | None = None, end: str | None = None,
                 root: str = config.ASSET):
        return _answer(lambda: store.patterns(rung, start, end, root))

    @app.get("/api/structure/{rung}")
    def structure(rung: str, start: str | None = None, end: str | None = None,
                  root: str = config.ASSET):
        return _answer(lambda: store.structure(rung, start, end, root))

    @app.get("/api/formations/{rung}")
    def formations(rung: str, start: str | None = None, end: str | None = None,
                   root: str = config.ASSET):
        return _answer(lambda: store.formations(rung, start, end, root))

    @app.get("/api/bands/{rung}")
    def bands(rung: str, root: str = "NQ", start: str | None = None, end: str | None = None):
        return _answer(lambda: store.bands(rung, root, start, end))

    @app.get("/api/memory/{ts}")
    def memory(ts: str, k: int = Query(config.MEMORY_K, ge=1, le=500)):
        return _answer(lambda: store.memory(ts, k))

    @app.get("/api/profiles")
    def profiles():
        return _answer(store.profiles)

    @app.get("/api/validation/{split}")
    def validation(split: str):
        return _answer(lambda: store.validation(split))

    @app.get("/api/dq")
    def dq():
        return _answer(store.dq)

    @app.get("/api/eod")
    def eod_index():
        return _answer(store.eod_index)

    @app.get("/api/eod/{d}")
    def eod(d: str):
        return _answer(lambda: store.eod(d))

    @app.get("/api/journal/{d}")
    def journal(d: str):
        return _answer(lambda: store.journal(d))

    @app.get("/api/rolling")
    def rolling():
        return _answer(store.rolling)

    @app.get("/api/registry")
    def registry():
        return _answer(store.registry)

    @app.get("/api/parity")
    def parity():
        return _answer(store.parity)

    @app.get("/api/live")
    def live():
        return _answer(store.live)

    @app.get("/api/user/drawings/{rung}")
    def get_drawings(rung: str):
        return _json(users.get_drawings(rung))

    @app.put("/api/user/drawings/{rung}")
    def put_drawings(rung: str, doc: Any = Body(None)):
        return _json(users.put_drawings(rung, doc))

    @app.get("/api/user/setups")
    def list_setups():
        return _json(users.list_setups())

    @app.get("/api/user/setups/{slug}")
    def get_setup(slug: str):
        out = users.get_setup(slug)
        return _json(out, 404 if out.get("exists") is False else 200)

    @app.put("/api/user/setups/{slug}")
    def put_setup(slug: str, doc: Any = Body(None)):
        return _json(users.put_setup(slug, doc))

    @app.delete("/api/user/setups/{slug}")
    def delete_setup(slug: str):
        out = users.delete_setup(slug)
        return _json(out, 404 if out.get("exists") is False else 200)

    return app
EOF
